#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C LCD(0x27, 16, 2);

#define I2C_SDA 5
#define I2C_SCL 4

void setup() {
  Serial.begin(115200);
  Wire.begin(I2C_SDA, I2C_SCL);

  LCD.init();
  LCD.backlight();
  LCD.clear();

  LCD.setCursor(0, 0);
  LCD.print("HELLO 1234567890");
  LCD.setCursor(0, 1);
  LCD.print("SECOND LINE OK");
}

void loop() {
  // мигаем подсветкой — если она мигает, питание и связь точно есть
  LCD.noBacklight();
  delay(500);
  LCD.backlight();
  delay(500);
}
